import type { Page } from "@playwright/test";
import { test, expect } from "./coverage";

// The public validation pages — /validation/ and one /validation/<case>/ page
// per benchmark — generated by examples/validation/run.mjs --report (which also
// checks, on every CI run, that their numbers still match the engine). These
// tests check that the pages are served, complete and indexable, and that the
// in-app reproduction holds: opening the linked example in KoFEM and solving
// it shows exactly the value the page publishes.

type Published = {
  engine: string;
  cases: { id: string; name: string }[];
  convergence: { id: string; series: { caseId: string }[] }[];
  reproduce: { galleryId: string; field: string; stat: string };
};

async function published(page: Page): Promise<Published> {
  const res = await page.request.get("/validation/results.json");
  expect(res.ok()).toBe(true);
  return (await res.json()) as Published;
}

// The value the app's Result summary shows for `stat` (e.g. "Max Ux").
function summaryValue(page: Page, stat: string) {
  return page
    .getByText(stat, { exact: true })
    .locator("xpath=following-sibling::span[1]");
}

async function showField(page: Page, field: string) {
  await page.getByTestId("tree-plot-1").click();
  await page.getByTestId("plot-field").selectOption(field);
}

test("/validation/ lists every benchmark, links its page and shows the disclaimer", async ({
  page,
}) => {
  const data = await published(page);
  await page.goto("/validation/");

  await expect(
    page.getByRole("heading", { level: 1, name: "Validation benchmarks" }),
  ).toBeVisible();
  await expect(page.locator('link[rel="canonical"]')).toHaveAttribute(
    "href",
    "https://kofem.org/validation/",
  );
  await expect(page.locator('meta[name="description"]')).toHaveAttribute(
    "content",
    /benchmark/,
  );
  await expect(page.getByTestId("disclaimer")).toContainText(
    "not certified for safety-critical design",
  );
  await expect(page.locator(".meta").first()).toContainText(
    `engine ${data.engine}`,
  );

  // One card per case, in the order of the published data, each linking to
  // the case's own page — and one results-table row per case doing the same.
  const cards = page.locator("[data-case]");
  await expect(cards).toHaveCount(data.cases.length);
  expect(
    await cards.evaluateAll((els) =>
      els.map((e) => e.getAttribute("data-case")),
    ),
  ).toEqual(data.cases.map((c) => c.id));
  for (const c of data.cases) {
    const card = page.locator(`[data-case="${c.id}"]`);
    await expect(card.getByRole("heading", { level: 3 })).toHaveText(c.name);
    await expect(card).toHaveAttribute("href", `/validation/${c.id}/`);
    await expect(
      page.locator("table.results").getByRole("link", { name: c.name }),
    ).toHaveAttribute("href", `/validation/${c.id}/`);
  }

  // Listed for crawlers: the overview and every case page.
  const sitemap = await (await page.request.get("/sitemap.xml")).text();
  expect(sitemap).toContain("<loc>https://kofem.org/validation/</loc>");
  for (const c of data.cases)
    expect(sitemap).toContain(
      `<loc>https://kofem.org/validation/${c.id}/</loc>`,
    );
});

test("every benchmark has its own indexable page with derivation and result", async ({
  page,
}) => {
  const data = await published(page);
  for (const [i, c] of data.cases.entries()) {
    await page.goto(`/validation/${c.id}/`);
    await expect(page.getByRole("heading", { level: 1 })).toHaveText(c.name);
    await expect(page.locator('link[rel="canonical"]')).toHaveAttribute(
      "href",
      `https://kofem.org/validation/${c.id}/`,
    );
    await expect(page.locator('meta[name="robots"]')).toHaveAttribute(
      "content",
      "index, follow",
    );
    const description = await page
      .locator('meta[name="description"]')
      .getAttribute("content");
    expect(description?.length ?? 0).toBeGreaterThan(50);
    const jsonLd = await page
      .locator('script[type="application/ld+json"]')
      .textContent();
    expect(JSON.parse(jsonLd ?? "")).toMatchObject({
      "@context": "https://schema.org",
    });

    await expect(page.getByTestId("fe-value")).not.toBeEmpty();
    for (const section of [
      "problem",
      "theory",
      "model",
      "results",
      "discussion",
      "reproduce",
      "references",
    ])
      await expect(page.locator(`h2#${section}`)).toBeVisible();
    await expect(page.locator("figure.diagram svg").first()).toBeVisible();
    await expect(page.locator("main math").first()).toBeVisible();
    await expect(page.locator("ol.refs li").first()).toBeVisible();
    await expect(page.getByTestId("disclaimer")).toBeVisible();
    await expect(page.locator("pre").first()).toContainText(
      `run.mjs --case ${c.id}`,
    );

    // The convergence study that covers this case, where there is one.
    const studies = data.convergence.filter((s) =>
      s.series.some((x) => x.caseId === c.id),
    );
    await expect(page.locator("[data-study]")).toHaveCount(studies.length);
    for (const s of studies)
      await expect(
        page.locator(`[data-study="${s.id}"] figure.chart svg`),
      ).toBeVisible();

    // Previous / next walk through the cases in order.
    const next = data.cases[i + 1];
    if (next)
      await expect(page.locator("a.step.next")).toHaveAttribute(
        "href",
        `/validation/${next.id}/`,
      );
  }
});

test("the page's in-app reproduction shows the published value", async ({
  page,
}) => {
  test.setTimeout(90_000);
  const { reproduce } = await published(page);
  await page.goto("/validation/");

  const readout = page.getByTestId("app-readout");
  await expect(readout).toHaveAttribute("data-stat", reproduce.stat);
  const value = await readout.getAttribute("data-value");
  if (!value)
    throw new Error("the page's app readout is missing its data-value");
  expect(value).toMatch(/^-?\d\.\d{3}e[+-]\d+ mm$/);

  // The page's link opens the gallery example in the app.
  await page.getByTestId("reproduce-open").click();
  await expect(page).toHaveURL(`/app/?example=${reproduce.galleryId}`);
  await expect(page.locator("nav")).toBeVisible();
  await page.waitForFunction(
    () =>
      (
        window as unknown as {
          __kofemStore?: { getState(): { nodes: unknown[] } };
        }
      ).__kofemStore?.getState().nodes.length,
    null,
    { timeout: 30_000 },
  );

  // Solve it in the browser (Studies → Static 1 → Run static solve), as the
  // page instructs: the example ships a stored result, which the solve replaces.
  await page.evaluate(() => {
    const win = window as unknown as {
      __kofemStore: { getState(): { result: unknown } };
      __storedResult: unknown;
    };
    win.__storedResult = win.__kofemStore.getState().result;
  });
  await page.getByTestId("tree-study-1").click();
  await page.getByRole("button", { name: /Run static solve/ }).click();
  await page.waitForFunction(
    () => {
      const win = window as unknown as {
        __kofemStore: { getState(): { result: unknown } };
        __storedResult: unknown;
      };
      const { result } = win.__kofemStore.getState();
      return result !== null && result !== win.__storedResult;
    },
    null,
    { timeout: 60_000 },
  );
  await showField(page, reproduce.field);
  await expect(summaryValue(page, reproduce.stat)).toHaveText(value);
});
